-- LeafLens treatments table (generated from assets/treatments.json)
create table if not exists public.treatments (
  label text primary key,
  cause text, severity text, summary text,
  do_now text[] default '{}', organic text[] default '{}',
  chemical text[] default '{}', prevent text[] default '{}'
);
alter table public.treatments enable row level security;
drop policy if exists "treatments readable by anyone" on public.treatments;
create policy "treatments readable by anyone" on public.treatments for select using (true);

